    const extractField = (fullText, startKey, endKey) => {
        // 1. Find where the start key begins (e.g., "title":)
        const startIdx = fullText.indexOf(`"${startKey}"`);
        if (startIdx === -1) return null;

        // 2. Determine where the value starts (after the colon)
        // We look for the first colon after the start key
        const colonIdx = fullText.indexOf(":", startIdx);
        if (colonIdx === -1) return null;

        // 3. Find the start of the NEXT key to know where to stop
        let endIdx;
        if (endKey) {
            endIdx = fullText.indexOf(`"${endKey}"`, colonIdx);
        } else {
            // If no endKey (it's the last item), look for the very last closing brace
            endIdx = fullText.lastIndexOf("}");
        }

        if (endIdx === -1) return null;

        // 4. Extract the raw chunk between them
        let rawValue = fullText.substring(colonIdx + 1, endIdx).trim();

        // 5. CLEANUP: Remove the trailing comma if it exists
        if (rawValue.endsWith(',')) {
            rawValue = rawValue.slice(0, -1).trim();
        }

        // 6. CLEANUP: Remove the surrounding quotes
        // This handles the specific issue of: "My "Title"" -> My "Title"
        if (rawValue.startsWith('"') && rawValue.endsWith('"')) {
            rawValue = rawValue.slice(1, -1);
        }

        // 7. Unescape standard JSON escapes (like \n or \") so the text is readable
        // We use a simple replace for common escapes to avoid JSON.parse errors
        try {
            // Try to interpret standard escapes
            rawValue = JSON.parse(`"${rawValue.replace(/"/g, '\\"')}"`);
        } catch (err) {
            // If that fails, just return the raw string with manual cleanup
            rawValue = rawValue.replace(/\\"/g, '"').replace(/\\n/g, '\n');
        }

        return rawValue;
    };

